  int addExternalInstancesOffset(int? offset) {
    fbBuilder.addOffset(10, offset);
    return fbBuilder.offset;
  }
  int addEmbeddedAssetsOffset(int? offset) {
    fbBuilder.addOffset(11, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class SsAnimeBinaryObjectBuilder extends fb.ObjectBuilder {
  final int? _version;
  final String? _name;
  final int? _nameHash;
  final List<PartDataObjectBuilder>? _parts;
  final List<AnimationDataObjectBuilder>? _animations;
  final List<CellMapObjectBuilder>? _cellmaps;
  final List<EffectObjectBuilder>? _effects;
  final List<SoundListObjectBuilder>? _soundLists;
  final List<FontBitmapObjectBuilder>? _fontBitmaps;
  final List<ExternalTextureObjectBuilder>? _externalTextures;
  final List<ExternalInstanceObjectBuilder>? _externalInstances;
  final List<EmbeddedAssetObjectBuilder>? _embeddedAssets;

  SsAnimeBinaryObjectBuilder({
    int? version,
    String? name,
    int? nameHash,
    List<PartDataObjectBuilder>? parts,
    List<AnimationDataObjectBuilder>? animations,
    List<CellMapObjectBuilder>? cellmaps,
    List<EffectObjectBuilder>? effects,
    List<SoundListObjectBuilder>? soundLists,
    List<FontBitmapObjectBuilder>? fontBitmaps,
    List<ExternalTextureObjectBuilder>? externalTextures,
    List<ExternalInstanceObjectBuilder>? externalInstances,
    List<EmbeddedAssetObjectBuilder>? embeddedAssets,
  })
      : _version = version,
        _name = name,
        _nameHash = nameHash,
        _parts = parts,
        _animations = animations,
        _cellmaps = cellmaps,
        _effects = effects,
        _soundLists = soundLists,
        _fontBitmaps = fontBitmaps,
        _externalTextures = externalTextures,
        _externalInstances = externalInstances,
        _embeddedAssets = embeddedAssets;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? nameOffset = _name == null ? null
        : fbBuilder.writeString(_name!);
    final int? partsOffset = _parts == null ? null
        : fbBuilder.writeList(_parts!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? animationsOffset = _animations == null ? null
        : fbBuilder.writeList(_animations!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? cellmapsOffset = _cellmaps == null ? null
        : fbBuilder.writeList(_cellmaps!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? effectsOffset = _effects == null ? null
        : fbBuilder.writeList(_effects!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? soundListsOffset = _soundLists == null ? null
        : fbBuilder.writeList(_soundLists!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? fontBitmapsOffset = _fontBitmaps == null ? null
        : fbBuilder.writeList(_fontBitmaps!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? externalTexturesOffset = _externalTextures == null ? null
        : fbBuilder.writeList(_externalTextures!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? externalInstancesOffset = _externalInstances == null ? null
        : fbBuilder.writeList(_externalInstances!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? embeddedAssetsOffset = _embeddedAssets == null ? null
        : fbBuilder.writeList(_embeddedAssets!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    fbBuilder.startTable(12);
    fbBuilder.addUint32(0, _version);
    fbBuilder.addOffset(1, nameOffset);
    fbBuilder.addUint32(2, _nameHash);
    fbBuilder.addOffset(3, partsOffset);
    fbBuilder.addOffset(4, animationsOffset);
    fbBuilder.addOffset(5, cellmapsOffset);
    fbBuilder.addOffset(6, effectsOffset);
    fbBuilder.addOffset(7, soundListsOffset);
    fbBuilder.addOffset(8, fontBitmapsOffset);
    fbBuilder.addOffset(9, externalTexturesOffset);
    fbBuilder.addOffset(10, externalInstancesOffset);
    fbBuilder.addOffset(11, embeddedAssetsOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
